class Solution {
    private static final int NEEDS_CAMERA = 0;
    private static final int HAS_CAMERA = 1;
    private static final int COVERED = 2;
    private int cameras;

    public int minCameraCover(TreeNode root) {
        cameras = 0;
        if (postorder(root) == NEEDS_CAMERA) {
            cameras++;
        }
        return cameras;
    }

    private int postorder(TreeNode node) {
        if (node == null) {
            return COVERED;
        }

        int left = postorder(node.left);
        int right = postorder(node.right);
        if (left == NEEDS_CAMERA || right == NEEDS_CAMERA) {
            cameras++;
            return HAS_CAMERA;
        }
        if (left == HAS_CAMERA || right == HAS_CAMERA) {
            return COVERED;
        }
        return NEEDS_CAMERA;
    }
}

class Solution {
    private static final int INF = 1_000_000;

    public int minCameraCover(TreeNode root) {
        int[] answer = dfs(root);
        return Math.min(answer[0], answer[1]);
    }

    private int[] dfs(TreeNode node) {
        if (node == null) {
            return new int[]{INF, 0, 0};
        }

        int[] left = dfs(node.left);
        int[] right = dfs(node.right);
        int withCamera = 1 + min(left[0], left[1], left[2])
                + min(right[0], right[1], right[2]);
        int coveredNoCamera = Math.min(
                left[0] + Math.min(right[0], right[1]),
                right[0] + Math.min(left[0], left[1]));
        int uncovered = left[1] + right[1];
        return new int[]{withCamera, coveredNoCamera, uncovered};
    }

    private int min(int a, int b, int c) {
        return Math.min(a, Math.min(b, c));
    }
}

import java.util.*;

class Solution {
    private static final int INF = 1_000_000;
    private final Map<TreeNode, int[][]> memo = new IdentityHashMap<>();

    public int minCameraCover(TreeNode root) {
        return Math.min(dp(root, 0, 0), dp(root, 0, 1));
    }

    private int dp(TreeNode node, int parentCamera, int hasCamera) {
        if (node == null) {
            return hasCamera == 1 ? INF : 0;
        }

        int[][] table = memo.computeIfAbsent(node, ignored -> {
            int[][] created = new int[2][2];
            for (int[] row : created) {
                Arrays.fill(row, -1);
            }
            return created;
        });
        if (table[parentCamera][hasCamera] != -1) {
            return table[parentCamera][hasCamera];
        }

        int best = INF;
        for (int leftCamera = 0; leftCamera <= 1; leftCamera++) {
            if (node.left == null && leftCamera == 1) {
                continue;
            }
            int leftCost = dp(node.left, hasCamera, leftCamera);
            if (leftCost >= INF) {
                continue;
            }
            for (int rightCamera = 0; rightCamera <= 1; rightCamera++) {
                if (node.right == null && rightCamera == 1) {
                    continue;
                }
                boolean covered = parentCamera == 1 || hasCamera == 1 || leftCamera == 1 || rightCamera == 1;
                if (!covered) {
                    continue;
                }
                int rightCost = dp(node.right, hasCamera, rightCamera);
                if (rightCost >= INF) {
                    continue;
                }
                best = Math.min(best, hasCamera + leftCost + rightCost);
            }
        }
        table[parentCamera][hasCamera] = best;
        return best;
    }
}

import java.util.*;

class Solution {
    private static final int NEEDS_CAMERA = 0;
    private static final int HAS_CAMERA = 1;
    private static final int COVERED = 2;

    public int minCameraCover(TreeNode root) {
        Map<TreeNode, Integer> state = new IdentityHashMap<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode current = root;
        TreeNode lastVisited = null;
        int cameras = 0;

        while (current != null || !stack.isEmpty()) {
            if (current != null) {
                stack.push(current);
                current = current.left;
            } else {
                TreeNode node = stack.peek();
                if (node.right != null && lastVisited != node.right) {
                    current = node.right;
                    continue;
                }

                int left = state.getOrDefault(node.left, COVERED);
                int right = state.getOrDefault(node.right, COVERED);
                if (left == NEEDS_CAMERA || right == NEEDS_CAMERA) {
                    cameras++;
                    state.put(node, HAS_CAMERA);
                } else if (left == HAS_CAMERA || right == HAS_CAMERA) {
                    state.put(node, COVERED);
                } else {
                    state.put(node, NEEDS_CAMERA);
                }
                lastVisited = stack.pop();
            }
        }

        if (state.getOrDefault(root, NEEDS_CAMERA) == NEEDS_CAMERA) {
            cameras++;
        }
        return cameras;
    }
}

import java.util.*;

class Solution {
    public int minCameraCover(TreeNode root) {
        Map<TreeNode, TreeNode> parent = new IdentityHashMap<>();
        List<TreeNode> order = new ArrayList<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);
        parent.put(root, null);

        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            order.add(node);
            if (node.left != null) {
                parent.put(node.left, node);
                stack.push(node.left);
            }
            if (node.right != null) {
                parent.put(node.right, node);
                stack.push(node.right);
            }
        }

        Set<TreeNode> covered = Collections.newSetFromMap(new IdentityHashMap<>());
        covered.add(null);
        int cameras = 0;
        for (int i = order.size() - 1; i >= 0; i--) {
            TreeNode node = order.get(i);
            if (covered.contains(node)) {
                continue;
            }

            TreeNode cameraNode = parent.get(node);
            if (cameraNode == null) {
                cameraNode = node;
            }
            cameras++;
            covered.add(cameraNode);
            covered.add(parent.get(cameraNode));
            covered.add(cameraNode.left);
            covered.add(cameraNode.right);
        }
        return cameras;
    }
}
